mapper.select:
SELECT id 'process.id', `name` 'process.name', task_type_enum, task_type_enum_sort, sort, IFNULL( sum( mete ), 0 ) mete, IFNULL( sum( price ), 0 ) price FROM ( SELECT price.id, price.NAME, price.task_type_enum, price.task_type_enum_sort, price.sort, MAX(price.mete)mete, SUM(price.price) price FROM ( SELECT price.team_reoprt_id, process.id, process.`name`, process.product_type task_type_enum, CASE process.product_type WHEN 1 THEN 1 WHEN 2 THEN 3 WHEN 16 THEN 2 END task_type_enum_sort, process.sort, CASE price.task_type_enum WHEN 1 THEN price.quantity * part.net_weight WHEN 2 THEN price.quantity * artifact.net_weight WHEN 16 THEN price.quantity * assemble.net_weight END mete, price.price FROM mes_building_produce_team_report_price price LEFT JOIN tech_artifact artifact ON artifact.id = price.product_id LEFT JOIN tech_assemble assemble ON assemble.id = price.product_id LEFT JOIN tech_machine_part part ON part.id = price.product_id LEFT JOIN mes_building_process process ON process.id = price.process_id LEFT JOIN mes_building_produce_team_report report ON report.id = price.team_reoprt_id LEFT JOIN mes_building_groups gro ON gro.id = report.groups_id
and date(price.create_time)>=date(#{startTime})
and date(price.create_time)<= date(#{endTime})
and gro.workshop_id =#{workshopId}
) price GROUP BY price.team_reoprt_id, price.id ) a GROUP BY id, `name`, task_type_enum, task_type_enum_sort, sort ORDER BY task_type_enum_sort, sort

SELECT temp.project_id, temp.id, temp.name, temp.sort, IFNULL(SUM(temp.mete), 0) mete, SUM(temp.price) price FROM ( SELECT process.id, process.`name`, process.sort, price.price, task.project_id, CASE price.task_type_enum WHEN 1 THEN part.net_weight * price.quantity WHEN 2 THEN artifact.net_weight * price.quantity ELSE assemble.net_weight * price.quantity END mete FROM mes_building_produce_team_report_price price LEFT JOIN mes_building_process process ON process.id = price.process_id LEFT JOIN mes_building_task task ON task.id = price.task_id LEFT JOIN tech_artifact artifact ON artifact.id = price.product_id AND price.task_type_enum = 2 LEFT JOIN tech_assemble assemble ON assemble.id = price.product_id AND price.task_type_enum = 16 LEFT JOIN tech_machine_part part ON part.id = price.product_id AND price.task_type_enum = 1 WHERE price.bool_delete_enum = 0
AND task.project_id in
#{id}
) temp GROUP BY temp.project_id, temp.id ORDER BY temp.project_id, temp.sort
